// dist/three-trial/engine/background-playback.js
function createBackgroundPlayback({ hidden, busy, tick, now = () => performance.now(), schedule = setTimeout, cancel = clearTimeout, onError = () => {
}, interval = 50 }) {
  let timer = null, last = null, stopped = false;
  function clear() {
    if (timer !== null) cancel(timer);
    timer = null;
    last = null;
  }
  function run() {
    timer = null;
    if (stopped || !hidden() || !busy()) {
      last = null;
      return;
    }
    const time = now(), dt2 = last === null ? 0 : Math.max(0, Math.min(0.1, (time - last) / 1e3));
    last = time;
    try {
      tick(dt2, time);
    } catch (error) {
      clear();
      onError(error);
      return;
    }
    wake2();
  }
  function wake2() {
    if (stopped || timer !== null || !hidden() || !busy()) return;
    timer = schedule(run, interval);
  }
  return { wake: wake2, visibility() {
    clear();
    wake2();
  }, stop() {
    stopped = true;
    clear();
  }, resume() {
    stopped = false;
    wake2();
  }, diagnostics: () => ({ scheduled: timer !== null }) };
}

